let currentWisdomIdx = 0;
let isWisdomAuto = true;
let wisdomProgress = 0;
let wisdomProgressInterval = null;
const wisdomDuration = 6000; // 6초

function renderWisdomChips() {
  const container = document.getElementById('thinkerAvatarChips');
  if (!container) return;
  container.innerHTML = mastersWisdomList.map((m, idx) => `
    <button onclick="selectWisdomThinker(${idx})" style="background: ${idx === currentWisdomIdx ? 'rgba(234, 179, 8, 0.25)' : 'rgba(255, 255, 255, 0.05)'}; border: 1px solid ${idx === currentWisdomIdx ? '#EAB308' : 'rgba(255, 255, 255, 0.12)'}; color: ${idx === currentWisdomIdx ? '#FACC15' : '#9CA3AF'}; padding: 6px 14px; border-radius: 980px; font-size: 0.82rem; font-weight: 700; cursor: pointer; display: flex; align-items: center; gap: 6px; transition: all 0.2s ease;">
      <span>${m.icon}</span>
      <span>${m.name}</span>
    </button>
  `).join('');
}

function selectWisdomThinker(idx) {
  currentWisdomIdx = (idx + mastersWisdomList.length) % mastersWisdomList.length;
  updateWisdomDisplay();
  resetWisdomTimer();
}

function nextWisdomThinker(delta) {
  selectWisdomThinker(currentWisdomIdx + delta);
}

function randomWisdom() {
  let nextIdx = Math.floor(Math.random() * mastersWisdomList.length);
  if (nextIdx === currentWisdomIdx) nextIdx = (nextIdx + 1) % mastersWisdomList.length;
  selectWisdomThinker(nextIdx);
}

function updateWisdomDisplay() {
  const m = mastersWisdomList[currentWisdomIdx];
  const content = document.getElementById('spotlightCardContent');
  if (!m || !content) return;

  content.style.opacity = '0';
  content.style.transform = 'translateY(6px)';

  setTimeout(() => {
    document.getElementById('spotlightIcon').textContent = m.icon;
    document.getElementById('spotlightName').textContent = m.name;
    document.getElementById('spotlightBadge').textContent = m.badge;
    document.getElementById('spotlightRole').textContent = m.role;
    document.getElementById('spotlightQuote').textContent = `"${m.quote}"`;
    document.getElementById('spotlightCommentary').textContent = m.commentary;
    document.getElementById('spotlightApplication').textContent = m.application;
    document.getElementById('spotlightSource').textContent = `출전: ${m.source}`;

    content.style.opacity = '1';
    content.style.transform = 'translateY(0)';
    renderWisdomChips();
  }, 150);
}

function resetWisdomTimer() {
  wisdomProgress = 0;
  const bar = document.getElementById('wisdomProgressBar');
  if (bar) bar.style.width = '0%';
}

function toggleWisdomAuto() {
  isWisdomAuto = !isWisdomAuto;
  const btn = document.getElementById('btnWisdomAutoToggle');
  if (btn) {
    btn.textContent = isWisdomAuto ? '⏸ 순환 일시정지' : '▶ 자동 순환 재개';
    btn.style.color = isWisdomAuto ? '#E5E7EB' : '#FACC15';
  }
}

function startWisdomLoop() {
  if (wisdomProgressInterval) clearInterval(wisdomProgressInterval);
  const step = 100;
  wisdomProgressInterval = setInterval(() => {
    if (!isWisdomAuto) return;
    wisdomProgress += step;
    const pct = Math.min(100, (wisdomProgress / wisdomDuration) * 100);
    const bar = document.getElementById('wisdomProgressBar');
    if (bar) bar.style.width = pct + '%';

    if (wisdomProgress >= wisdomDuration) {
      nextWisdomThinker(1);
    }
  }, step);
}

