function renderMacroIndPills() {
  const container = document.getElementById('macroIndCatPills');
  if (!container) return;
  container.innerHTML = macroIndCategories.map(c => `
    <button class="sub-filter-pill ${c.id === currentMacroIndCat ? 'active' : ''}" onclick="setMacroIndCat('${c.id}')" style="padding: 4px 10px; font-size: 0.76rem;">
      ${c.label}
    </button>
  `).join('');
}

function setMacroIndCat(catId) {
  currentMacroIndCat = catId;
  renderMacroIndPills();
  renderMacroIndCards();
}

function handleMacroIndSearch() {
  const input = document.getElementById('macroIndSearchInput');
  currentMacroIndQuery = input ? input.value.trim().toLowerCase() : '';
  renderMacroIndCards();
}

function resetMacroIndFilter() {
  const input = document.getElementById('macroIndSearchInput');
  if (input) input.value = '';
  currentMacroIndQuery = '';
  currentMacroIndCat = 'all';
  renderMacroIndPills();
  renderMacroIndCards();
}

function filterMacroInds() {
  return macroIndicatorsMaster.filter(item => {
    if (currentMacroIndCat !== 'all' && item.category !== currentMacroIndCat) return false;
    if (currentMacroIndQuery) {
      const matchName = item.name.toLowerCase().includes(currentMacroIndQuery);
      const matchEn = item.name_en.toLowerCase().includes(currentMacroIndQuery);
      const matchSource = item.source.toLowerCase().includes(currentMacroIndQuery);
      const matchCat = item.category.toLowerCase().includes(currentMacroIndQuery);
      const matchInsight = item.insight.toLowerCase().includes(currentMacroIndQuery);
      if (!matchName && !matchEn && !matchSource && !matchCat && !matchInsight) return false;
    }
    return true;
  });
}

function renderMacroIndCards() {
  const container = document.getElementById('macroIndResultsGrid');
  if (!container) return;
  const filtered = filterMacroInds();

  if (filtered.length === 0) {
    container.innerHTML = `
      <div style="grid-column: 1 / -1; padding: 24px; text-align: center; color: #86868B;">
        일치하는 경제지표가 없습니다. 다른 검색어를 입력해 보세요.
      </div>
    `;
    return;
  }

  container.innerHTML = filtered.map(item => {
    let badgeColor = '#38bdf8';
    if (item.nature === '선행') badgeColor = '#38bdf8';
    else if (item.nature === '동행') badgeColor = '#10b981';
    else badgeColor = '#f59e0b';

    return `
      <div style="background: rgba(255, 255, 255, 0.03); border: 1px solid rgba(255, 255, 255, 0.08); border-radius: 10px; padding: 12px 14px; display: flex; flex-direction: column; justify-content: space-between; transition: all 0.2s;" onmouseover="this.style.borderColor='rgba(56, 189, 248, 0.4)'; this.style.background='rgba(255, 255, 255, 0.05)';" onmouseout="this.style.borderColor='rgba(255, 255, 255, 0.08)'; this.style.background='rgba(255, 255, 255, 0.03)';">
        <div>
          <div style="display: flex; justify-content: space-between; align-items: center; margin-bottom: 6px;">
            <span style="font-size: 0.72rem; color: #94A3B8; font-weight: 600;">${item.category} · ${item.freq}</span>
            <span style="font-size: 0.68rem; font-weight: 800; color: ${badgeColor}; background: rgba(255,255,255,0.06); padding: 2px 6px; border-radius: 4px;">
              ${item.nature}
            </span>
          </div>
          <div style="font-size: 0.92rem; font-weight: 800; color: #FFFFFF; line-height: 1.3; margin-bottom: 2px;">
            ${item.name}
          </div>
          <div style="font-size: 0.72rem; color: #64748B; margin-bottom: 8px;">
            ${item.name_en} · ${item.source}
          </div>
          <div style="font-size: 1.15rem; font-weight: 900; color: #FACC15; margin-bottom: 8px;">
            ${item.current_val}
          </div>
          <p style="font-size: 0.78rem; color: #A1A1AA; line-height: 1.45; margin: 0 0 10px 0; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden;">
            ${item.insight}
          </p>
        </div>
        <div style="display: flex; justify-content: space-between; align-items: center; border-top: 1px solid rgba(255,255,255,0.05); padding-top: 8px;">
          <button onclick="selectMacroIndicatorForChart('${item.id}')" style="background: none; border: none; color: #38bdf8; font-size: 0.75rem; font-weight: 700; cursor: pointer; padding: 0;">
            📈 시계열 분석 &gt;
          </button>
          <a href="${item.url}" target="_blank" style="color: #64748B; font-size: 0.72rem; text-decoration: none;">
            통계원 ↗
          </a>
        </div>
      </div>
    `;
  }).join('');
}

function selectMacroIndicatorForChart(id) {
  switchEconTab('tab-inception');
  const select = document.getElementById('econInceptionSelect');
  if (select) {
    select.value = id;
    renderInceptionTimeSeries();
  }
  const el = document.getElementById('tab-inception');
  if (el) el.scrollIntoView({ behavior: 'smooth' });
}

